using System.Security.Cryptography;
using System.Text.Json;
using MphRead.Mods.Network;

// Explicit writer-frontier fixtures using immutable values from an actual ordinary recording.
internal static class CustomReplayWriterChecks
{
    internal static int Run(string input,string output)
    {
        int checks=0;
        try
        {
            input=Path.GetFullPath(input);if(Directory.Exists(input))input=Path.Combine(input,"actual-full-custom"+DemoFile.Extension);output=Path.GetFullPath(output);Directory.CreateDirectory(output);if(new FileInfo(input).Length is <=0 or >128*1024*1024)throw new InvalidDataException("Bounded actual recording required.");string sourceHash=Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(input)));string loaded=typeof(ReplayWritePump).Assembly.Location;string loadedHash=Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(loaded)));Console.WriteLine("Loaded ProjectPrime: "+loaded+" SHA256="+loadedHash);
            void Check(bool ok,string label){if(!ok)throw new InvalidDataException(label);checks++;}
            using var source=DemoReader.Open(input,out var opened);Check(source!=null&&opened==ReplayOpenResult.Success&&source.Metadata is{FormatVersion:7,WorldCheckpoint.Length:>0},"actual custom world recording metadata admitted");var metadata=source!.Metadata!;DemoRecord? actual=null;int scanned=0;while(source.ReadNext() is{} item){if(++scanned>32768)throw new InvalidDataException("Source scan bound.");if(item.Frame>0&&item.Data.Length>0&&item.Data[0]!=255){actual=item;break;}}Check(actual.HasValue,"actual first positive packet available");Check(source.Checkpoints.Count>0,"actual durable world checkpoint available");var checkpointIndex=source.Checkpoints.First(index=>index.Frame>0);byte[] checkpoint=source.ReadCheckpoint(checkpointIndex);var receipt=new List<object>();
            foreach(bool checkpointCase in new[]{false,true})
            {
                uint frontier=checkpointCase?checkpointIndex.Frame:actual!.Value.Frame;string name=checkpointCase?"checkpoint-frontier":"record-frontier";string path=Path.Combine(output,name+DemoFile.Extension);if(File.Exists(path))throw new InvalidDataException("Preserve existing frontier output.");var pump=new ReplayWritePump(path,metadata,metadata.OriginRecordingFrame);Check(pump.EndFrame(0)&&pump.EndFrame(frontier-1),"queued quiet frontier trails actual source "+name);uint absolute=checked(metadata.OriginRecordingFrame+frontier);byte[] bytes=checkpointCase?checkpoint:actual!.Value.Data;var record=new ReplayTimelineRecord(absolute,0,checkpointCase?ReplayFactKind.World:bytes[0]==ReplayCustomWeaponFact.Tag?ReplayFactKind.CustomWeapon:ReplayFactKind.Presentation,bytes);try{Check(checkpointCase?pump.Checkpoint(record):pump.Record(record),"actual immutable data command queued "+name);}finally{record.Release();}pump.Complete();Check(pump.Completion.Wait(TimeSpan.FromSeconds(15)),"writer completes within bound "+name);pump.Completion.GetAwaiter().GetResult();Check(pump.Error==null&&pump.QueuedBytes==0&&File.Exists(path)&&!File.Exists(path+".part"),"clean close and retained command release "+name);
                using var reader=DemoReader.Open(path,out var result);Check(reader!=null&&result==ReplayOpenResult.Success&&reader.DurationFrames==frontier,"record/checkpoint extends final duration without subsequent EndFrame "+name);int quiet=0,packets=0;bool exact=false;while(reader!.ReadNext() is{} item){Check(item.Frame>0,"no frame-zero command emitted "+name);if(item.Data[0]==255){quiet++;Check(item.Data.Length==1&&item.Frame==frontier,"quiet marker appears only at actual final frontier "+name);}else{packets++;exact|=item.Frame==frontier&&item.Data.SequenceEqual(bytes);}}Check(reader.LastResult==ReplayOpenResult.Success&&quiet==1,"single final marker and entire stream closes successfully "+name);if(checkpointCase)Check(reader.Checkpoints.Count==1&&reader.Checkpoints[0].Frame==frontier&&reader.ReadCheckpoint(reader.Checkpoints[0]).SequenceEqual(checkpoint),"actual durable checkpoint bytes retained unchanged");else Check(exact&&packets==1,"actual first positive packet bytes retained unchanged");receipt.Add(new{name,frontier,absolute,quiet,packets,queuedBytesAfter=pump.QueuedBytes,actualWriterCompleted=pump.Completion.IsCompletedSuccessfully});
            }
            // Synthetic storage-pressure fixture only: the payload remains the actual recorded packet.
            string overflowPath=Path.Combine(output,"byte-budget-overflow"+DemoFile.Extension);using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())
            {
                var actualRecord=new ReplayTimelineRecord(checked(metadata.OriginRecordingFrame+actual!.Value.Frame),0,actual.Value.Data[0]==ReplayCustomWeaponFact.Tag?ReplayFactKind.CustomWeapon:ReplayFactKind.Presentation,actual.Value.Data);bool completed=false;var pump=new ReplayWritePump(overflowPath,metadata,metadata.OriginRecordingFrame,maximumBytes:128+actualRecord.PayloadBytes-1,beforeWrite:()=>{entered.Set();if(!release.Wait(TimeSpan.FromSeconds(10)))throw new TimeoutException("Bounded writer test barrier timed out.");});
                try{Check(pump.EndFrame(0),"custom writer enters bounded barrier with pending final frontier");Check(entered.Wait(TimeSpan.FromSeconds(3)),"worker actually blocks before processing queued frame");Check(!pump.Record(actualRecord),"actual payload refuses custom write-pump byte-budget overflow");}
                finally{release.Set();pump.Complete();completed=pump.Completion.Wait(TimeSpan.FromSeconds(15));actualRecord.Release();}
                Check(completed&&pump.Error is IOException&&pump.Error.Message.Contains("byte budget",StringComparison.OrdinalIgnoreCase),"overflow finishes with explicit storage budget error");Check(pump.QueuedBytes==0&&!File.Exists(overflowPath),"failed custom writer releases all queued bytes and publishes no final file/marker");receipt.Add(new{name="byte-budget-overflow",actualWriterCompleted=completed,error=pump.Error!.Message,queuedBytesAfter=pump.QueuedBytes,finalPublished=File.Exists(overflowPath)});
            }
            Check(sourceHash==Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(input))),"actual source recording remains byte-identical");File.WriteAllText(Path.Combine(output,"writer-frontier-results.json"),JsonSerializer.Serialize(new{checks,source=input,sourceSha256=sourceHash,loadedAssembly=loaded,loadedSha256=loadedHash,receipt,scope="Asset-free asynchronous writer frontier fixtures using actual recording metadata, native/custom packet and durable world bytes. No new accepted gameplay, Scene, combat or rendering claim. Custom byte-budget failure is checked here; native replay-format suite retains other cancellation/backpressure coverage."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS {checks} custom replay writer frontier checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY WRITER FAIL "+error);return 1;}
    }
}
